// Blog (/blog/): portfolio & art/design study-abroad articles from content/blog.json.
// Everything is pre-rendered static HTML (body text is in the page without JS) for readers and for
// search / answer engines: per-post JSON-LD (BlogPosting, BreadcrumbList, optional FAQPage), canonical,
// Open Graph / Twitter tags, hreflang when a post has an English version, an Atom feed, and the
// site-wide sitemap.xml / robots.txt / llms.txt / llms-full.txt generated by build/build.mjs.
//
// content/blog.json = { "author": { "sameAs": [urls] }, "posts": [post] }
// post = {
//   "slug": "lowercase-with-hyphens",             // URL /blog/<slug>/
//   "title": { "zh-Hant": "…", "en": "…" },       // zh primary; en optional (a plain string = zh only)
//   "date": "YYYY-MM-DD", "updated": "YYYY-MM-DD", // published / last updated (updated optional)
//   "categories": ["school-selection", …],         // 1+ of BLOG_CATEGORIES ids
//   "cover": "assets/blog/<slug>/cover.webp",      // optional, local file (never a WeChat URL)
//   "summary": { "zh-Hant": "…", "en": "…" },     // 1–2 sentences: meta description + listing
//   "tldr": { "zh-Hant": "…", "en": "…" },        // short direct answer shown in a box at the top
//   "body": { "zh-Hant": "<h2>…？</h2><p>…</p>", "en": "…" },  // trusted HTML; H2s phrased as questions
//   "keywords": ["…"], "faq": [{ "q": {…}, "a": {…} }],        // optional
//   "source": { "type": "wechat", "date": "YYYY-MM-DD", "url": "…" },   // optional (original publication)
//   "abstract_en": "…",                            // optional ~120-word English summary (shown as a block; also in llms-full.txt)
//   Student works in body: <div class="work-grid"><figure class="post-work"><a href="../../board/<slug>/"><img src="../../assets/board/<slug>/NN.webp" …></a>
//     <figcaption><strong>Title</strong>｜caption (no student names)<br><a class="work-link" href="../../board/<slug>/">看完整作品：Title →</a></figcaption></figure>…</div>
//     Reuse the matching board pin images; works with no board match keep a local assets/blog/<slug>/ image and no link.
//   "draft": true                                   // optional: page built with noindex, not listed
// }
import { esc, safeUrl, assetUrl, headExtra, cssV, langHead, LANG_SWITCH_JS, LANGS, LANG_LABEL, LANG_NAME,
  topBar, SITE_URL, SITE_DESCRIPTION, personJsonLd, siteJsonLd, jsonLdScript, listedPins, teachingStudios, finishPage } from './render.js';

export const BLOG_CATEGORIES = [
  { id: 'school-selection', 'zh-Hant': '選校策略', en: 'School selection' },
  { id: 'portfolio-strategy', 'zh-Hant': '作品集呈現策略', en: 'Portfolio strategy' },
  { id: 'essay', 'zh-Hant': '申請文書', en: 'Essay' },
  { id: 'dream-school', 'zh-Hant': '夢校申請策略', en: 'Dream-school strategy' },
  { id: 'top-school', 'zh-Hant': '頂尖學院申請解析', en: 'Top-school requirements' }
];
const CAT = Object.fromEntries(BLOG_CATEGORIES.map(c => [c.id, c]));
export const AUTHOR_NAME = 'Yu Chun Tsai';
export const AUTHOR_FACTS = {
  'zh-Hant': '2017 年至今，設計教學與設計諮詢時數合計 12,000+ 小時・370+ 位學生・1,800+ 個錄取。',
  en: 'Since 2017: 12,000+ combined hours of design teaching and design consultation · 370+ students · 1,800+ offers.'
};
export const ADMISSIONS = ['Princeton University', 'Harvard University', 'MIT', 'Columbia University', 'Cornell University', 'UC Berkeley',
  'Rice University', 'University of Cambridge', 'UCL', 'Politecnico di Milano', 'KU Leuven', 'TU Berlin', 'Lund University',
  'KTH Royal Institute of Technology', 'The University of Hong Kong', 'National University of Singapore'];
// 發表於 = the original publication date (source.date when the post was first published elsewhere), 更新於 = latest update.
export const firstPub = p => (p.source && /^\d{4}-\d{2}-\d{2}$/.test(p.source.date || '') ? p.source.date : p.date);
const UI = {
  blog: { 'zh-Hant': '部落格', en: 'Blog' },
  lead: { 'zh-Hant': '作品集與藝術／設計留學申請的經驗分享：選校、作品集、文書與頂尖學院解析。', en: 'Notes on portfolios and art / design study-abroad applications: school selection, portfolio strategy, essays and what top schools look for.' },
  all: { 'zh-Hant': '全部', en: 'All' },
  empty: { 'zh-Hant': '即將上線', en: 'Coming soon' },
  none: { 'zh-Hant': '這個分類暫時沒有文章。', en: 'No posts in this category yet.' },
  tldr: { 'zh-Hant': '重點摘要', en: 'TL;DR' },
  faq: { 'zh-Hant': '常見問題', en: 'FAQ' },
  updated: { 'zh-Hant': '更新於', en: 'Updated' },
  published: { 'zh-Hant': '發表於', en: 'Published' },
  related: { 'zh-Hant': '相關文章', en: 'Related posts' },
  author: { 'zh-Hant': '作者', en: 'Author' },
  role: { 'zh-Hant': '建築與設計作品集導師（Mentor）・香港 S&J Design 資深外聘設計顧問', en: 'Architecture & design portfolio mentor · Senior External Design Consultant, S&J Design, Hong Kong' },
  cvLink: { 'zh-Hant': '完整履歷', en: 'Full CV' },
  boardLink: { 'zh-Hant': '學生作品', en: 'Student projects' },
  teachLink: { 'zh-Hant': '教學與工作營', en: 'Teaching & workshops' },
  consultLink: { 'zh-Hant': '一對一諮詢', en: 'One-to-one consulting' }
};

// A localized field: { "zh-Hant", "en" } or a plain string (= Chinese only).
export const loc = (v, l) => (v && typeof v === 'object' ? String(v[l] || '') : (l === 'zh-Hant' && typeof v === 'string' ? v : '')).trim();
const zhOr = v => loc(v, 'zh-Hant') || loc(v, 'en');
export const postHasEn = p => !!(loc(p.title, 'en') && loc(p.body, 'en'));
const plain = h => String(h || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
const clip = (t, n) => (t.length > n ? t.slice(0, n - 1).replace(/\s+\S*$/, '') + '…' : t);
export const postUrl = slug => SITE_URL + '/blog/' + slug + '/';
export const postPath = slug => 'blog/' + slug + '/index.html';
export const postCats = p => (Array.isArray(p.categories) ? p.categories : [p.categories]).filter(c => CAT[c]);
export const blogPostsAll = blog => (blog && Array.isArray(blog.posts) ? blog.posts : []).filter(p => p && p.slug && p.visible !== false);
// Listed posts (not drafts), newest first (by date, then slug).
export const blogPosts = blog => blogPostsAll(blog).filter(p => p.draft !== true)
  .slice().sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')) || String(a.slug).localeCompare(String(b.slug)));

// Text in both languages when it differs (CSS shows the chosen one); untagged when only one exists.
function bi(v, tag, langs, raw) {
  const f = x => (raw ? x : esc(x));
  if (langs.length < 2) { const t = zhOr(v); return t ? '<' + tag + '>' + f(t) + '</' + tag + '>' : ''; }
  return langs.map(l => { const t = loc(v, l) || zhOr(v); return t ? '<' + tag + ' data-l="' + l + '" lang="' + l + '">' + f(t) + '</' + tag + '>' : ''; }).join('');
}
const langButtons = () => '<div class="langs" role="group" aria-label="Language">' + LANGS.map(l => '<button type="button" data-set-lang="' + l + '" lang="' + l + '" title="' + esc(LANG_NAME[l]) + '">' + esc(LANG_LABEL[l]) + '</button>').join('') + '</div>';
const catLabel = (id, langs) => bi(CAT[id], 'span', langs);

function socialMeta(o) {
  return '<meta name="description" content="' + esc(o.description) + '">\n' +
    '<link rel="canonical" href="' + esc(o.url) + '">\n' +
    (o.hreflang ? '<link rel="alternate" hreflang="zh-Hant" href="' + esc(o.url) + '">\n<link rel="alternate" hreflang="en" href="' + esc(o.url) + '?lang=en">\n<link rel="alternate" hreflang="x-default" href="' + esc(o.url) + '">\n' : '') +
    '<meta property="og:type" content="' + o.type + '">\n<meta property="og:site_name" content="Yu Chun Tsai">\n' +
    '<meta property="og:title" content="' + esc(o.title) + '">\n<meta property="og:description" content="' + esc(o.description) + '">\n' +
    '<meta property="og:url" content="' + esc(o.url) + '">\n<meta property="og:locale" content="zh_TW">\n' + (o.hreflang ? '<meta property="og:locale:alternate" content="en_US">\n' : '') +
    (o.image ? '<meta property="og:image" content="' + esc(o.image) + '">\n' : '') +
    '<meta name="twitter:card" content="' + (o.image ? 'summary_large_image' : 'summary') + '">\n<meta name="twitter:title" content="' + esc(o.title) + '">\n<meta name="twitter:description" content="' + esc(o.description) + '">\n' +
    (o.image ? '<meta name="twitter:image" content="' + esc(o.image) + '">\n' : '') +
    '<link rel="alternate" type="application/atom+xml" title="Yu Chun Tsai — Blog" href="' + SITE_URL + '/blog/feed.xml">\n';
}
const absAsset = src => (!src ? '' : /^https?:/i.test(src) ? src : SITE_URL + '/' + String(src).replace(/^\/+/, ''));

/* ---------- /blog/ ---------- */
// Category filter in the URL hash (#cat=<id>), like the board's filters; "all" shows every post.
const BLOG_FILTER_JS = '<script>(function(){var bs=[].slice.call(document.querySelectorAll("[data-blog-cat]")),ps=[].slice.call(document.querySelectorAll(".post-card")),none=document.querySelector(".blog-none");' +
  'function cur(){var m=/(?:^#|&)cat=([a-z-]+)/.exec(location.hash);var c=m?m[1]:"all";return bs.some(function(b){return b.getAttribute("data-blog-cat")===c})?c:"all"}' +
  'function apply(){var c=cur(),n=0;bs.forEach(function(b){var on=b.getAttribute("data-blog-cat")===c;b.classList.toggle("on",on);b.setAttribute("aria-pressed",on?"true":"false")});' +
  'ps.forEach(function(p){var show=c==="all"||(" "+p.getAttribute("data-cat")+" ").indexOf(" "+c+" ")>=0;p.hidden=!show;if(show)n++});if(none)none.hidden=!(ps.length&&!n)}' +
  'bs.forEach(function(b){b.addEventListener("click",function(){var c=b.getAttribute("data-blog-cat");history.replaceState(null,"",c==="all"?location.pathname+location.search:"#cat="+c);apply()})});' +
  'window.addEventListener("hashchange",apply);apply()})();</script>\n';

export function renderBlogIndex(site, blog, opts) {
  const posts = blogPosts(blog), L = LANGS;
  const url = SITE_URL + '/blog/';
  const ld = { '@context': 'https://schema.org', '@graph': [personJsonLd(),
    { '@type': 'Blog', '@id': url + '#blog', url, name: 'Yu Chun Tsai — Blog', description: loc(UI.lead, 'en'), inLanguage: 'zh-Hant', author: { '@id': SITE_URL + '/#person' },
      blogPost: posts.map(p => ({ '@type': 'BlogPosting', headline: zhOr(p.title), url: postUrl(p.slug), datePublished: p.date, dateModified: p.updated || p.date })) },
    breadcrumbs([['Home', SITE_URL + '/'], ['Blog', url]])] };
  let h = '<!doctype html><html lang="zh-Hant"><head>' + headExtra(opts) + '<meta charset="utf-8"><title>部落格 Blog — 作品集與藝術設計留學 — ' + esc(site.name) + '</title>\n' +
    '<meta name="viewport" content="width=device-width,initial-scale=1">\n' +
    socialMeta({ type: 'website', title: '部落格 Blog — ' + site.name, description: loc(UI.lead, 'zh-Hant') + ' ' + loc(UI.lead, 'en'), url, hreflang: true }) +
    jsonLdScript(ld) + langHead(L) +
    '<link rel="stylesheet" href="../style.css' + cssV(opts) + '"></head><body class="blog-page">\n' +
    topBar(site, 1, 'blog') +
    '<main class="blog">\n<div class="blog-head"><h1>' + bi(UI.blog, 'span', L) + '</h1>' + langButtons() + '</div>\n' +
    '<p class="blog-lead">' + bi(UI.lead, 'span', L) + '</p>\n' +
    '<div class="board-tools blog-tools"><div class="filters" role="group" aria-label="Category">' +
    [{ id: 'all' }].concat(BLOG_CATEGORIES).map(c => '<button type="button" data-blog-cat="' + c.id + '"' + (c.id === 'all' ? ' class="on" aria-pressed="true"' : ' aria-pressed="false"') + '>' +
      bi(c.id === 'all' ? UI.all : c, 'span', L) + (c.id === 'all' ? '' : ' <small>' + posts.filter(p => postCats(p).includes(c.id)).length + '</small>') + '</button>').join('') +
    '</div></div>\n';
  if (!posts.length) h += '<p class="blog-empty">' + bi(UI.empty, 'span', L) + '</p>\n';
  else {
    h += '<ul class="post-list">\n' + posts.map(p => postCard(p, 1, L)).join('') + '</ul>\n';
    h += '<p class="blog-none" hidden>' + bi(UI.none, 'span', L) + '</p>\n';
  }
  return finishPage(h + '</main>\n' + BLOG_FILTER_JS + LANG_SWITCH_JS + '</body></html>\n', 1);
}
function postCard(p, depth, L) {
  const cats = postCats(p);
  return '  <li class="post-card" data-cat="' + esc(cats.join(' ')) + '"><a href="' + (depth === 1 ? '' : '../') + esc(p.slug) + '/">' +
    (p.cover ? '<img src="' + esc(assetUrl(p.cover, depth)) + '" alt="" draggable="false" loading="lazy">' : '') +
    '<span class="pc-text"><span class="pc-meta"><time datetime="' + esc(p.date) + '">' + esc(p.date) + '</time> · ' + cats.map(c => catLabel(c, L)).join(' / ') + '</span>' +
    '<strong class="pc-title">' + bi(p.title, 'span', L) + '</strong>' +
    (zhOr(p.summary) ? '<span class="pc-sum">' + bi(p.summary, 'span', L) + '</span>' : '') + '</span></a></li>\n';
}
function breadcrumbs(items) {
  return { '@type': 'BreadcrumbList', itemListElement: items.map(([name, item], i) => ({ '@type': 'ListItem', position: i + 1, name, item })) };
}

/* ---------- /blog/<slug>/ ---------- */
export function relatedPosts(blog, post, n = 3) {
  const cats = postCats(post), others = blogPosts(blog).filter(p => p.slug !== post.slug);
  const score = p => postCats(p).filter(c => cats.includes(c)).length;
  return others.filter(p => score(p) > 0).sort((a, b) => score(b) - score(a)).concat(others.filter(p => score(p) === 0)).slice(0, n);
}
export function postJsonLd(post) {
  const url = postUrl(post.slug), en = postHasEn(post);
  const g = [personJsonLd(),
    { '@type': 'BlogPosting', '@id': url + '#article', mainEntityOfPage: url, url,
      headline: zhOr(post.title), ...(en ? { alternativeHeadline: loc(post.title, 'en') } : {}),
      description: zhOr(post.summary) || clip(plain(zhOr(post.body)), 160),
      datePublished: post.date, dateModified: post.updated || post.date,
      inLanguage: en ? ['zh-Hant', 'en'] : 'zh-Hant',
      author: { '@type': 'Person', '@id': SITE_URL + '/#person', name: AUTHOR_NAME, url: SITE_URL + '/cv/' },
      publisher: { '@id': SITE_URL + '/#person' },
      ...(post.cover ? { image: absAsset(post.cover) } : {}),
      ...(Array.isArray(post.keywords) && post.keywords.length ? { keywords: post.keywords.join(', ') } : {}),
      articleSection: postCats(post).map(c => CAT[c].en),
      isPartOf: { '@id': SITE_URL + '/blog/#blog' } },
    breadcrumbs([['Home', SITE_URL + '/'], ['Blog', SITE_URL + '/blog/'], [zhOr(post.title), url]])];
  const faq = (Array.isArray(post.faq) ? post.faq : []).filter(f => f && zhOr(f.q) && zhOr(f.a));
  if (faq.length) g.push({ '@type': 'FAQPage', '@id': url + '#faq', mainEntity: faq.map(f => ({ '@type': 'Question', name: plain(zhOr(f.q)), acceptedAnswer: { '@type': 'Answer', text: plain(zhOr(f.a)) } })) });
  return { '@context': 'https://schema.org', '@graph': g };
}
export function renderBlogPost(site, blog, post, opts) {
  const en = postHasEn(post), L = en ? LANGS : ['zh-Hant'], url = postUrl(post.slug), cats = postCats(post);
  const sameAs = blog && blog.author && Array.isArray(blog.author.sameAs) ? blog.author.sameAs.filter(Boolean) : [];
  const ld = postJsonLd(post); if (sameAs.length) ld['@graph'][0].sameAs = sameAs;
  const title = zhOr(post.title);
  const desc = clip(zhOr(post.summary) || plain(zhOr(post.body)), 160);
  const ui = (k, tag = 'span') => bi(UI[k], tag, L);
  const faq = (Array.isArray(post.faq) ? post.faq : []).filter(f => f && zhOr(f.q) && zhOr(f.a));
  let h = '<!doctype html><html lang="zh-Hant"><head>' + headExtra(opts) + '<meta charset="utf-8"><title>' + esc(title) + (en ? ' | ' + esc(loc(post.title, 'en')) : '') + ' — ' + esc(site.name) + '</title>\n' +
    '<meta name="viewport" content="width=device-width,initial-scale=1">\n' +
    (post.draft === true ? '<meta name="robots" content="noindex,nofollow">\n' : '') +
    socialMeta({ type: 'article', title, description: desc, url, hreflang: en, image: absAsset(post.cover) }) +
    '<meta property="article:published_time" content="' + esc(post.date) + '">\n<meta property="article:modified_time" content="' + esc(post.updated || post.date) + '">\n<meta property="article:author" content="' + SITE_URL + '/cv/">\n' +
    (Array.isArray(post.keywords) && post.keywords.length ? '<meta name="keywords" content="' + esc(post.keywords.join(', ')) + '">\n' : '') +
    jsonLdScript(ld) + (en ? langHead(LANGS) : '') +
    '<link rel="stylesheet" href="../../style.css' + cssV(opts) + '"></head><body class="blog-post-page">\n' +
    topBar(site, 2, 'blog') +
    '<main class="post">\n<div class="crumbs"><nav aria-label="Breadcrumb"><a href="../">' + ui('blog') + '</a>' + cats.map(c => ' / <a href="../#cat=' + c + '">' + catLabel(c, L) + '</a>').join('') + '</nav>' + (en ? langButtons() : '') + '</div>\n' +
    '<article>\n<h1>' + bi(post.title, 'span', L) + '</h1>\n' +
    '<p class="post-meta"><span>' + ui('published') + ' <time datetime="' + esc(firstPub(post)) + '">' + esc(firstPub(post)) + '</time></span>' +
    (post.updated && post.updated !== firstPub(post) ? ' · <span>' + ui('updated') + ' <time datetime="' + esc(post.updated) + '">' + esc(post.updated) + '</time></span>' : '') +
    ' · <span>' + AUTHOR_NAME + '</span></p>\n';
  if (zhOr(post.tldr)) h += '<aside class="tldr"><p class="tldr-h">' + ui('tldr') + '</p>' + bi(post.tldr, 'p', L) + '</aside>\n';
  if (post.cover) h += '<figure class="post-cover"><img src="' + esc(assetUrl(post.cover, 2)) + '" alt="' + esc(title) + '" draggable="false"></figure>\n';
  h += '<div class="post-body">' + (L.length > 1 ? L.map(l => '<div data-l="' + l + '" lang="' + l + '">\n' + (loc(post.body, l) || zhOr(post.body)) + '\n</div>').join('') : '\n' + zhOr(post.body) + '\n') + '</div>\n';
  if (post.abstract_en) h += '<section class="en-abstract" lang="en"><h2>English summary</h2><p>' + esc(post.abstract_en) + '</p></section>\n';
  if (faq.length) h += '<section class="faq"><h2>' + ui('faq') + '</h2>\n' + faq.map(f => '<details open><summary>' + bi(f.q, 'span', L) + '</summary>' + bi(f.a, 'p', L) + '</details>\n').join('') + '</section>\n';
  // post.source (original publication) stays internal data only; it is not shown on the page.
  h += '</article>\n' +
    '<section class="author-box"><p class="ab-h">' + ui('author') + '</p><p class="ab-name"><a href="../../cv/">' + AUTHOR_NAME + '</a></p>' +
    '<p class="ab-role">' + ui('role') + '</p><p class="ab-facts">' + bi(AUTHOR_FACTS, 'span', L) + '</p>' +
    '<p class="ab-links"><a href="../../cv/">' + ui('cvLink') + '</a> · <a href="../../board/">' + ui('boardLink') + '</a> · <a href="../../teaching/">' + ui('teachLink') + '</a> · <a href="../../consulting/">' + ui('consultLink') + '</a></p></section>\n';
  const rel = relatedPosts(blog, post);
  if (rel.length) h += '<section class="related"><h2>' + ui('related') + '</h2><ul class="post-list">\n' + rel.map(p => postCard(p, 2, L)).join('') + '</ul></section>\n';
  return finishPage(h + '</main>\n' + (en ? LANG_SWITCH_JS : '') + '</body></html>\n', 2);
}

/* ---------- feed, sitemap, robots, llms ---------- */
const xml = s => esc(s).replace(/'/g, '&apos;');
export function renderFeed(blog, now) {
  const posts = blogPosts(blog);
  const upd = posts.map(p => p.updated || p.date).sort().pop() || now;
  return '<?xml version="1.0" encoding="utf-8"?>\n<feed xmlns="http://www.w3.org/2005/Atom" xml:lang="zh-Hant">\n' +
    '  <title>Yu Chun Tsai — Blog</title>\n  <subtitle>' + xml(loc(UI.lead, 'en')) + '</subtitle>\n' +
    '  <link href="' + SITE_URL + '/blog/feed.xml" rel="self"/>\n  <link href="' + SITE_URL + '/blog/"/>\n  <id>' + SITE_URL + '/blog/</id>\n' +
    '  <updated>' + upd + 'T00:00:00Z</updated>\n  <author><name>' + AUTHOR_NAME + '</name><uri>' + SITE_URL + '/cv/</uri></author>\n' +
    posts.map(p => '  <entry>\n    <title>' + xml(zhOr(p.title)) + '</title>\n    <link href="' + postUrl(p.slug) + '"/>\n    <id>' + postUrl(p.slug) + '</id>\n' +
      '    <published>' + p.date + 'T00:00:00Z</published>\n    <updated>' + (p.updated || p.date) + 'T00:00:00Z</updated>\n' +
      postCats(p).map(c => '    <category term="' + c + '" label="' + xml(CAT[c].en) + '"/>\n').join('') +
      '    <summary>' + xml(zhOr(p.summary) || clip(plain(zhOr(p.body)), 200)) + '</summary>\n  </entry>\n').join('') +
    '</feed>\n';
}
// urls: [{ loc: 'https://…', lastmod: 'YYYY-MM-DD' }]
export function renderSitemap(urls) {
  return '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' +
    urls.map(u => '  <url><loc>' + xml(u.loc) + '</loc>' + (u.lastmod ? '<lastmod>' + u.lastmod + '</lastmod>' : '') + '</url>\n').join('') + '</urlset>\n';
}
export const AI_BOTS = ['GPTBot', 'OAI-SearchBot', 'ChatGPT-User', 'ClaudeBot', 'Claude-Web', 'anthropic-ai', 'PerplexityBot', 'Perplexity-User',
  'Google-Extended', 'Googlebot', 'Bingbot', 'Applebot', 'Applebot-Extended', 'CCBot', 'DuckDuckBot'];
export function renderRobots() {
  return '# yuchuntsai.com — search and AI answer engines are welcome to crawl and cite this site.\n' +
    AI_BOTS.map(b => 'User-agent: ' + b + '\nAllow: /\nDisallow: /admin/\n').join('\n') +
    '\nUser-agent: *\nAllow: /\nDisallow: /admin/\n\nSitemap: ' + SITE_URL + '/sitemap.xml\n';
}
